{
  "name": "ask_user",
  "arguments": {
    "query": "¿Quieres que me enfoque en técnicas específicas (como memoria externa, ventanas deslizantes, etc.) o en aplicaciones prácticas? ¿Buscas métodos ya implementados o investigación experimental?"
